def rot2(yaw):
    return np.array([[math.cos(yaw), -math.sin(yaw)], [math.sin(yaw), math.cos(yaw)]])


def wrap(x):
    return (x + math.pi) % (2 * math.pi) - math.pi


def first(x):
    """Drop the leading batch axis of size 1 that the evaluator puts in front of every observation."""
    a = np.asarray(x)
    return a[0] if a.ndim >= 2 and a.shape[0] == 1 else a


# ---- image helpers (replace cv2) ------------------------------------------------------------------------
def resize_nearest(d, n):
    d = np.squeeze(d); h = d.shape[0]
    if h == n: return d
    idx = np.minimum(np.floor(np.arange(n) * (h / n)).astype(int), h - 1)
    return d[idx][:, idx]


def resize_area(im, n):
    """Box-overlap (INTER_AREA) downscale of a square HxWx3 uint8 image to n x n."""
    h = im.shape[0]
    if h == n: return im
    s = h / n; lo = (np.arange(n) * s)[:, None]; ov = np.clip(np.minimum(lo + s, np.arange(h)[None] + 1.) - np.maximum(lo, np.arange(h)[None]), 0, None); w = (ov / s).astype(np.float32)
    t = np.tensordot(w, im.astype(np.float32), axes=(1, 0)); out = np.tensordot(t, w, axes=(1, 1)).transpose(0, 2, 1)
    return np.clip(np.rint(out), 0, 255).astype(np.uint8)


def components(mask):
    """8-connected components like cv2.connectedComponentsWithStats: (count incl. background, labels, x y w h area)."""
    labels, n = label(mask, structure=np.ones((3, 3))); stats = np.zeros((n + 1, 5), int); stats[:, 4] = np.bincount(labels.ravel(), minlength=n + 1)
    for i, sl in enumerate(find_objects(labels), 1): stats[i, :4] = sl[1].start, sl[0].start, sl[1].stop - sl[1].start, sl[0].stop - sl[0].start
    return n + 1, labels, stats


def dilate(m, size):
    return maximum_filter(m, size=size, mode="nearest")


def red_mask(rgb):
    a = rgb.astype(float)
    return (a[..., 0] > 85) & (a[..., 0] > 2.5 * a[..., 1] + 20) & (a[..., 0] > 2.5 * a[..., 2] + 20)


def make_cameras(frame, size=256, images=True):
    """Camera dicts (role -> rgb, depth, K, R, t) in the robot frame. images=False skips the resize (poses only)."""
    rel = frame["robot_r1::cam_rel_poses"].reshape(3, 7); cams = {}
    for i, (role, link, focal) in enumerate(CAMERAS):
        prefix = f"robot_r1::robot_r1:{link}:Camera:0::"; w = frame[prefix + "rgb"].shape[1]; width = w if size is None else size
        K = np.array([[focal * width, 0, width / 2], [0, focal * width, width / 2], [0, 0, 1.]]); rot = R.from_quat(rel[i, 3:]).as_matrix() @ np.diag([1, -1, -1]); im = depth = None
        if images:
            depth = resize_nearest(frame[prefix + "depth_linear"], width); im = resize_area(frame[prefix + "rgb"][..., :3], width)
        cams[role] = {"rgb": im, "depth": depth, "K": K, "R": rot, "t": rel[i, :3]}
    return cams


def pointcloud(cam, mask=None, stride=1):
    d = cam["depth"]; valid = np.isfinite(d) & (d > .06) & (d < 5)
    if mask is not None: valid &= mask
    y, x = np.where(valid); y, x = y[::stride], x[::stride]; z = d[y, x]; p = np.c_[(x + .5 - cam["K"][0, 2]) / cam["K"][0, 0] * z, (y + .5 - cam["K"][1, 2]) / cam["K"][1, 1] * z, z]
    return p @ cam["R"].T + cam["t"], cam["rgb"][y, x], np.c_[x, y]


def touches_border(m):
    return bool(m[0].any() or m[-1].any() or m[:, 0].any() or m[:, -1].any())


# ---- kinematics (JOINTS table instead of the URDF) --------------------------------------------------------
class Kinematics:
    """FK and geometric Jacobians for the chains base->zed_link and base->right finger tip. q: torso 4, right arm 7, 2 fingers."""
    def __init__(self):
        self.joints = []
        for dof, parent, child, kind, xyz, rpy, axis in JOINTS:
            t = np.eye(4); t[:3, 3] = xyz; t[:3, :3] = R.from_euler("xyz", rpy).as_matrix(); self.joints.append((dof, parent, child, kind, t, np.asarray(axis)))
    def forward(self, q):
        poses, axes, anc = {"base_link": np.eye(4)}, {}, {"base_link": []}
        for dof, parent, child, kind, origin, axis in self.joints:
            t = poses[parent] @ origin; motion = np.eye(4); v = q[dof] if dof >= 0 else 0.
            if kind == "revolute": motion[:3, :3] = R.from_rotvec(axis * v).as_matrix()
            elif kind == "prismatic": motion[:3, 3] = axis * v
            axes[dof] = (t[:3, 3], t[:3, :3] @ axis, kind); poses[child] = t @ motion; anc[child] = anc[parent] + ([dof] if dof >= 0 else [])
        return poses, axes, anc
    def jacobian(self, link, q, point=None, cache=None):
        poses, axes, anc = cache or self.forward(q); t = poses[link]; xyz = t[:3, 3] if point is None else t[:3, 3] + t[:3, :3] @ point; jac = np.zeros((6, len(q)))
        for dof in anc[link]:
            pos, axis, kind = axes[dof]
            if kind == "prismatic": jac[:3, dof] = axis
            else:
                jac[:3, dof] = np.cross(axis, xyz - pos); jac[3:, dof] = axis
        return jac


def from_proprio(s):
    return np.r_[s[53:57], s[28:35], s[49:51]].astype(float)


def solve_lsq(fun, x, lo, hi, max_nfev=140):
    """Bounded Levenberg-Marquardt with a forward-difference Jacobian (stands in for scipy least_squares)."""
    r = fun(x); cost, lam = r @ r, 1e-2
    for _ in range(max_nfev):
        J = np.empty((len(r), len(x)))
        for k in range(len(x)):
            h = 1e-6 * max(1., abs(x[k])) * (1 if x[k] + 1e-6 * max(1., abs(x[k])) <= hi[k] else -1); xk = x.copy(); xk[k] += h; J[:, k] = (fun(xk) - r) / h
        A, g = J.T @ J, J.T @ r
        while lam < 1e12:
            xn = np.clip(x - np.linalg.solve(A + lam * np.diag(np.diag(A) + 1e-9), g), lo, hi); rn = fun(xn)
            if rn @ rn < cost: break
            lam *= 4
        else:
            return x
        done = cost - rn @ rn < 1e-12 * cost or np.linalg.norm(xn - x) < 1e-9; x, r, cost, lam = xn, rn, rn @ rn, max(lam / 3, 1e-9)
        if done: break
    return x


# ---- perception: known radio localisation from RGB-D ---------------------------------------------------------
def check_template(counts, blob):
    """Raise a clear error when the packed priors are damaged (truncated, edited, or COUNTS not matching the point count)."""
    n_colours, n_bytes, expected = TEMPLATE_CHECK
    data = np.concatenate([blob, (counts % 256).astype(np.uint8), (counts // 256).astype(np.uint8)]).astype(np.uint64)
    got = int((data * (np.arange(len(data), dtype=np.uint64) % 251 + 1)).sum() % 4294967291)
    if len(blob) != n_bytes or len(counts) != n_colours or counts.sum() * 3 + n_colours * 3 != n_bytes or got != expected:
        raise ValueError(f"radio template priors are damaged: blob bytes {len(blob)} (expected {n_bytes}), colours {len(counts)} "
                         f"(expected {n_colours}), points by COUNTS {int(counts.sum())} (expected {(n_bytes - 3 * n_colours) // 3}), "
                         f"checksum {got} (expected {expected}). Restore TEMPLATE_COUNTS and TEMPLATE_BLOB from build_priors.py.")


def load_template():
    counts = np.asarray(TEMPLATE_COUNTS, np.int64); codes = np.frombuffer(B64.encode("ascii"), np.uint8); order = np.argsort(codes)
    v = order[np.searchsorted(codes[order], np.frombuffer(TEMPLATE_BLOB.encode("ascii"), np.uint8))].reshape(-1, 4).astype(np.uint32)
    word = (v[:, 0] << 18) | (v[:, 1] << 12) | (v[:, 2] << 6) | v[:, 3]
    blob = np.stack([word >> 16, (word >> 8) & 255, word & 255], axis=1).astype(np.uint8).reshape(-1); check_template(counts, blob)
    palette = blob[:3 * len(counts)].reshape(-1, 3); q = blob[3 * len(counts):].reshape(-1, 3).astype(float)
    return np.asarray(TEMPLATE_LO) + q / 255 * np.asarray(TEMPLATE_SPAN), palette[np.repeat(np.arange(len(counts)), counts)]


class RadioPose:
    def __init__(self):
        self.xyz, self.rgb = load_template(); self.button = np.asarray(BUTTON, float); self.red = red_mask(self.rgb); self.last = None
    def render(self, p, cam):
        rot = R.from_euler("xyz", [p[4], p[5], p[3]]).as_matrix(); world = self.xyz @ rot.T + p[:3]; pts = (world - cam["t"]) @ cam["R"]; uv = pts @ cam["K"].T
        uv = uv[:, :2] / np.maximum(uv[:, 2:], 1e-8); xy = np.floor(uv).astype(int); h, w = cam["rgb"].shape[:2]
        good = (pts[:, 2] > .05) & (xy[:, 0] >= 0) & (xy[:, 0] < w) & (xy[:, 1] >= 0) & (xy[:, 1] < h); idx = np.flatnonzero(good); pix = xy[idx, 1] * w + xy[idx, 0]
        order = np.lexsort((pts[idx, 2], pix)); idx, pix = idx[order], pix[order]
        if len(idx):
            unique = np.r_[True, pix[1:] != pix[:-1]]; idx, pix = idx[unique], pix[unique]
        im = np.zeros((h * w, 3), np.uint8); z = np.zeros(h * w); im[pix] = self.rgb[idx]; z[pix] = pts[idx, 2]
        return im.reshape(h, w, 3), z.reshape(h, w)
    def pick_views(self, cams):
        views = []
        for role, cam in cams.items():
            red = red_mask(cam["rgb"]); n, labels, stats = components(red); order = np.argsort(stats[1:, 4])[::-1] + 1
            for lab in order[:4]:
                if stats[lab, 4] < 6: continue
                local = labels == lab; p, _, _ = pointcloud(cam, local)
                if len(p) < 6: continue
                center = np.median(p, axis=0); p = p[np.linalg.norm(p - center, axis=1) < .35]
                if len(p) < 6 or center[2] < .08 or center[2] > .9: continue
                # Several red pieces of one rigid radio may be disconnected.
                cloud, _, pix = pointcloud(cam, red); select = np.linalg.norm(cloud - center, axis=1) < .32; local[:] = False; local[pix[select, 1], pix[select, 0]] = True; visible = cloud[select]
                extent = np.sort(np.ptp(visible, axis=0)) if len(visible) else np.zeros(3)
                # Close, clipped wrist views constrain a switch but cannot identify the whole-object pose.
                if (role != "head" and touches_border(local)) or extent[-1] * extent[-2] < .012 or extent[-1] > .44 \
                        or np.linalg.norm(extent) > .60:
                    continue
                views.append((role, cam, local, visible))
                break
        return views
    def fit(self, cams, global_search=False, allow_fallen=False):
        views = self.pick_views(cams)
        if not views: return None
        # Prefer the head unless a wrist sees substantially more of the radio.
        views = sorted(views, key=lambda v: len(v[3]) * (2.0 if v[0] == "head" else 1) * (.15 if touches_border(v[2]) else 1.),
                       reverse=True)
        role, cam, truth, cloud = views[0]; cloud = cloud[::max(1, len(cloud) // 1000)]; centroid = np.mean(cloud, axis=0)
        # A point-cloud template can leak far-side colours through sampling holes: score the white rim and dark inside.
        rgb = cam["rgb"].astype(float); white = dilate(((rgb.min(-1) > 135) & ((rgb.max(-1) - rgb.min(-1)) < 65)).astype(np.float32), 3); dark = (rgb.max(-1) < 105).astype(np.float32)
        theta = np.linspace(0, 2 * np.pi, 24, endpoint=False); ring = np.c_[np.full(24, .03801), self.button[1] + .052 * np.cos(theta), self.button[2] + .052 * np.sin(theta)]
        inside = np.c_[np.full(24, .03801), self.button[1] + .030 * np.cos(theta), self.button[2] + .030 * np.sin(theta)]
        def speaker_score(params):
            rot = R.from_euler("xyz", [params[4], params[5], params[3]]).as_matrix(); center = params[:3] + rot @ self.button; toward = cam["t"] - center; distance = np.linalg.norm(toward)
            if rot[:, 0] @ toward / max(distance, 1e-8) < .25: return 0.
            samples = np.concatenate([ring, inside]) @ rot.T + params[:3]; view = (samples - cam["t"]) @ cam["R"]; uv = view @ cam["K"].T; uv = uv[:, :2] / np.maximum(uv[:, 2:], 1e-8)
            pixels = np.floor(uv).astype(int); h, w = white.shape
            if not np.all((pixels[:, 0] >= 0) & (pixels[:, 0] < w) & (pixels[:, 1] >= 0) & (pixels[:, 1] < h) & (view[:, 2] > .05)): return 0.
            observed = cam["depth"][pixels[:, 1], pixels[:, 0]]
            # An intervening hand legitimately hides the feature; never penalise that occlusion.
            if np.mean(observed < view[:, 2] - .035) > .3: return 0.
            white_support = white[pixels[:24, 1], pixels[:24, 0]].mean(); dark_support = dark[pixels[24:, 1], pixels[24:, 0]].mean()
            resolution = min(1., .052 * cam["K"][0, 0] / max(distance, 1e-8) / 4.)
            return .7 * (.8 - white_support - .8 * dark_support) * resolution
        def loss(params):
            if np.linalg.norm(params[:3] - centroid) > .22: return 100.
            image, z = self.render(params, cam); mask = z > 0; pred = red_mask(image); iou = (pred & truth).sum() / max(1, (pred | truth).sum()); observed = cam["depth"]
            pixels = mask & np.isfinite(observed) & (observed > .05); depth = np.minimum(np.abs(z[pixels] - observed[pixels]), .2).mean() if pixels.any() else .2
            photo = np.abs(image.astype(float) - cam["rgb"].astype(float))[pixels].mean() / 255 if pixels.any() else 1.
            return 1 - iou + .5 * photo + 6 * depth + speaker_score(params)
        candidates = []
        if self.last is not None and not global_search: candidates = [(loss(self.last), self.last.copy())]
        else:
            tilts = [(0., -.05)]
            if allow_fallen: tilts += [(0., np.pi / 2), (0., -np.pi / 2), (np.pi / 2, 0.), (-np.pi / 2, 0.), (np.pi, 0.)]
            for roll, pitch in tilts:
                for angle in np.linspace(-np.pi, np.pi, 72, endpoint=False):
                    rot = R.from_euler("xyz", [roll, pitch, angle]).as_matrix(); model = self.xyz[self.red] @ rot.T; pos = centroid - model.mean(0); tree = cKDTree(model)
                    for _ in range(10):
                        dist, idx = tree.query(cloud - pos); pos = np.median(cloud - model[idx], axis=0)
                    params = np.r_[pos, angle, roll, pitch]; candidates.append((loss(params), params))
        best = sorted(candidates, key=lambda x: x[0])[:5]
        for step, ang in [(.015, .15), (.006, .07), (.003, .03), (.0015, .015)]:
            candidates = list(best)
            for _, params in best:
                for axis, scale in enumerate([step, step, step, ang, ang, ang]):
                    for sign in [-1, 1]:
                        p = params.copy(); p[axis] += sign * scale; candidates.append((loss(p), p))
            best = sorted(candidates, key=lambda x: x[0])[:4]
        score, p = best[0]; self.last = p.copy(); rot = R.from_euler("xyz", [p[4], p[5], p[3]]).as_matrix()
        return {"position": p[:3], "rotation": rot, "button": p[:3] + rot @ self.button, "score": score, "view": role,
                "pixels": len(cloud), "params": p, "clipped": touches_border(truth), "visible_center": centroid.copy()}


def speaker_ring(cams, predicted):
    """Fit the known white speaker rim from RGB-D; no segmentation or object pose input."""
    candidates = []; rng = np.random.default_rng(4821)
