def red_button(cams, predicted, normal):
    """Find the isolated red switch in an onboard view near the model affordance."""
    candidates = []
    for role in ["right_wrist", "left_wrist", "head"]:
        cam = cams[role]; n, labels, stats = components(red_mask(cam["rgb"])); h, w = labels.shape
        for i in range(1, n):
            x, y, bw, bh, area = stats[i]
            if area < (12 if role == "head" else 20) or x <= 1 or y <= 1 or x + bw >= w - 1 or y + bh >= h - 1: continue
            if max(bw, bh) > min(bw, bh) * 2.5: continue
            pts, _, _ = pointcloud(cam, labels == i)
            if len(pts) < 15: continue
            center = np.median(pts, axis=0); extent = np.linalg.norm(np.ptp(pts, axis=0)); distance = np.linalg.norm(center - predicted)
            if not (.018 < extent < .085 and distance < .055): continue
            # Front-panel normal from the surrounding dark RGB-D pixels (resolves front/back template ambiguity).
            panel_normal, measured_normal = np.asarray(normal).copy(), False; ring = dilate((labels == i).astype(np.uint8), 9) > 0; ring &= (labels != i) & (cam["rgb"].max(axis=-1) < 95)
            panel, _, _ = pointcloud(cam, ring); panel = panel[np.linalg.norm(panel - center, axis=1) < .065]
            if len(panel) >= 20:
                origin = np.median(panel, axis=0); _, singular, axes = np.linalg.svd(panel - origin, full_matrices=False)
                if singular[-1] < .22 * singular[-2] and singular[-2] > .015:
                    panel_normal = axes[-1]
                    if panel_normal @ (cam["t"] - center) < 0: panel_normal = -panel_normal
                    measured_normal = True
            # The visible coloured cap sits just in front of the switch's contact volume.
            point = center - panel_normal * .007; pad = max(bw, bh) // 2; crop = cam["rgb"][max(0, y - pad):min(h, y + bh + pad), max(0, x - pad):min(w, x + bw + pad)]
            dark = (crop.max(axis=-1) < 95).mean()
            if dark < .12: continue
            candidates.append((distance + .2 * abs(extent - .05) + .02 * (1 - dark), point, panel_normal, measured_normal))
    if not candidates: return None
