class DepthMap:
    def __init__(self):
        self.res, self.n = .06, 160; self.hits = np.zeros((160, 160), np.uint16)
    def ij(self, xy):
        return np.floor(np.asarray(xy) / self.res + self.n / 2).astype(int)
    def xy(self, ij):
        return (np.asarray(ij) - self.n / 2 + .5) * self.res
